<?php
namespace App\Http\Controllers\Api\V1;
use App\Http\Controllers\Controller;use App\Models\{Client,FieldCheckpoint,FieldFile,FieldFormTemplate,FieldWorkOrder,Project,SafetyIncident,WorkspaceMember};use App\Services\Access\WorkScopeService;use Illuminate\Http\JsonResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;use Illuminate\Support\Str;use Illuminate\Validation\Rule;
/** Provides field workforce controller behavior within the WorkIntel application. */ class FieldWorkforceController extends Controller{
 /** Handles the overview operation for the current WorkIntel workflow. */ public function overview(Request $request,WorkScopeService $scope):JsonResponse{$w=$request->attributes->get('workspace');$a=$request->attributes->get('workspaceMember');$ids=$this->visibleMemberIds($a,$scope);$orders=FieldWorkOrder::where('workspace_id',$w->id)->whereHas('assignees',fn($q)=>$q->whereIn('member_id',$ids))->with(['assignees.member.user:id,first_name,last_name','project:id,name,code','client:id,name'])->orderByDesc('id')->get();$incidents=SafetyIncident::where('workspace_id',$w->id)->whereIn('reporter_member_id',$ids)->orderByDesc('occurred_at')->limit(100)->get();return response()->json(['work_orders'=>$orders,'incidents'=>$incidents,'forms'=>FieldFormTemplate::where('workspace_id',$w->id)->with('fields')->orderBy('name')->get(),'checkpoints'=>FieldCheckpoint::where('workspace_id',$w->id)->orderBy('name')->get(['id','uuid','project_id','name','type','token_prefix','latitude','longitude','radius_meters','status']),'people'=>WorkspaceMember::where('workspace_id',$w->id)->whereIn('id',$ids)->with('user:id,first_name,last_name')->get(['id','user_id','employee_code']),'projects'=>Project::where('workspace_id',$w->id)->where('status','active')->get(['id','name','code']),'clients'=>Client::where('workspace_id',$w->id)->orderBy('name')->get(['id','name']),'can_manage'=>$a->hasPermission('field.manage')]);}
 /** Handles the store order operation for the current WorkIntel workflow. */ public function storeOrder(Request $request,WorkScopeService $scope):JsonResponse{$w=$request->attributes->get('workspace');$a=$request->attributes->get('workspaceMember');$d=$request->validate(['title'=>'required|string|max:180','description'=>'nullable|string|max:10000','project_id'=>'nullable|integer','client_id'=>'nullable|integer','priority'=>['required',Rule::in(['low','normal','high','urgent'])],'scheduled_start_at'=>'nullable|date','scheduled_end_at'=>'nullable|date|after_or_equal:scheduled_start_at','due_at'=>'nullable|date','site_name'=>'nullable|string|max:180','site_address'=>'nullable|string|max:500','latitude'=>'nullable|numeric|between:-90,90','longitude'=>'nullable|numeric|between:-180,180','geofence_radius_meters'=>'nullable|integer|min:20|max:50000','instructions'=>'nullable|string|max:10000','member_ids'=>'required|array|min:1','member_ids.*'=>'integer']);$allowed=$this->visibleMemberIds($a,$scope);foreach($d['member_ids'] as $id)abort_unless(in_array((int)$id,$allowed,true),403,'One or more assignees are outside your field-team scope.');if($d['project_id']??null)Project::where('workspace_id',$w->id)->findOrFail($d['project_id']);if($d['client_id']??null)Client::where('workspace_id',$w->id)->findOrFail($d['client_id']);$members=$d['member_ids'];unset($d['member_ids']);$row=FieldWorkOrder::create(['uuid'=>(string)Str::uuid(),'workspace_id'=>$w->id,'work_order_number'=>$this->nextNumber($w->id),'status'=>'assigned','created_by'=>$request->user()->id,...$d]);foreach($members as $id)$row->assignees()->create(['member_id'=>$id,'role'=>'assignee']);return response()->json(['data'=>$row->load('assignees.member.user')],201);}
 /** Updates update order data for the requested resource. */ public function updateOrder(Request $request,FieldWorkOrder $order,WorkScopeService $scope):JsonResponse{$w=$request->attributes->get('workspace');$a=$request->attributes->get('workspaceMember');abort_unless((int)$order->workspace_id===(int)$w->id,404);$allowed=$this->visibleMemberIds($a,$scope);abort_unless($order->assignees()->whereIn('member_id',$allowed)->exists(),403);$d=$request->validate(['title'=>'sometimes|string|max:180','description'=>'nullable|string|max:10000','status'=>['sometimes',Rule::in(['assigned','accepted','in_progress','blocked','completed','canceled'])],'priority'=>['sometimes',Rule::in(['low','normal','high','urgent'])],'due_at'=>'nullable|date','instructions'=>'nullable|string|max:10000','member_ids'=>'nullable|array','member_ids.*'=>'integer']);if(isset($d['member_ids'])){foreach($d['member_ids'] as $id)abort_unless(in_array((int)$id,$allowed,true),403);$ids=$d['member_ids'];unset($d['member_ids']);$order->assignees()->delete();foreach($ids as $id)$order->assignees()->create(['member_id'=>$id,'role'=>'assignee']);}$order->update($d);return response()->json(['data'=>$order->fresh('assignees.member.user')]);}
 /** Handles the store checkpoint operation for the current WorkIntel workflow. */ public function storeCheckpoint(Request $request):JsonResponse{$w=$request->attributes->get('workspace');$d=$request->validate(['name'=>'required|string|max:160','type'=>['required',Rule::in(['qr','nfc','both'])],'project_id'=>'nullable|integer','latitude'=>'nullable|numeric|between:-90,90','longitude'=>'nullable|numeric|between:-180,180','radius_meters'=>'nullable|integer|min:20|max:50000']);if($d['project_id']??null)Project::where('workspace_id',$w->id)->findOrFail($d['project_id']);$raw='wifc_'.Str::random(48);$row=FieldCheckpoint::create(['uuid'=>(string)Str::uuid(),'workspace_id'=>$w->id,'name'=>$d['name'],'type'=>$d['type'],'project_id'=>$d['project_id']??null,'scan_token_hash'=>hash('sha256',$raw),'token_prefix'=>substr($raw,0,12),'latitude'=>$d['latitude']??null,'longitude'=>$d['longitude']??null,'radius_meters'=>$d['radius_meters']??null,'status'=>'active','created_by'=>$request->user()->id]);return response()->json(['data'=>$row->only(['id','uuid','name','type','token_prefix','status']),'scan_token'=>$raw,'warning'=>'Copy this checkpoint token now; the server stores only its hash.'],201);}
 /** Handles the store form operation for the current WorkIntel workflow. */ public function storeForm(Request $request):JsonResponse{$w=$request->attributes->get('workspace');$d=$request->validate(['name'=>'required|string|max:160','category'=>'required|string|max:50','requires_work_order'=>'boolean','requires_location'=>'boolean','fields'=>'required|array|min:1','fields.*.key'=>'required|string|max:80','fields.*.label'=>'required|string|max:180','fields.*.type'=>['required',Rule::in(['text','number','boolean','select','multiselect','photo','signature','date'])],'fields.*.required'=>'boolean','fields.*.options'=>'nullable|array','fields.*.validation'=>'nullable|array']);$fields=$d['fields'];unset($d['fields']);$row=FieldFormTemplate::create(['uuid'=>(string)Str::uuid(),'workspace_id'=>$w->id,'status'=>'active','created_by'=>$request->user()->id,...$d]);foreach($fields as $i=>$field)$row->fields()->create([...$field,'position'=>$i+1]);return response()->json(['data'=>$row->load('fields')],201);}
 /** Handles the review incident operation for the current WorkIntel workflow. */ public function reviewIncident(Request $request,SafetyIncident $incident):JsonResponse{$w=$request->attributes->get('workspace');abort_unless((int)$incident->workspace_id===(int)$w->id,404);$d=$request->validate(['status'=>['required',Rule::in(['open','investigating','resolved','closed'])],'resolution'=>'nullable|string|max:10000']);$incident->update(['status'=>$d['status'],'resolution'=>$d['resolution']??$incident->resolution,'reviewed_by'=>$request->user()->id,'reviewed_at'=>now()]);return response()->json(['data'=>$incident->fresh()]);}
 /** Handles the download file operation for the current WorkIntel workflow. */ public function downloadFile(Request $request,FieldFile $file,WorkScopeService $scope){$w=$request->attributes->get('workspace');$a=$request->attributes->get('workspaceMember');abort_unless((int)$file->workspace_id===(int)$w->id,404);if(!$a->hasPermission('field.manage'))abort_unless($file->member_id===$a->id||in_array((int)$file->member_id,$this->visibleMemberIds($a,$scope),true),403);abort_unless(Storage::disk('local')->exists($file->file_path),404);return Storage::disk('local')->download($file->file_path,$file->file_name);}
 /** Handles the visible member ids operation for the current WorkIntel workflow. */ private function visibleMemberIds(WorkspaceMember $a,WorkScopeService $scope):array{if($a->hasPermission('people.view_all')||$a->hasPermission('people.manage'))return WorkspaceMember::where('workspace_id',$a->workspace_id)->where('status','active')->pluck('id')->map(fn($id)=>(int)$id)->all();return $scope->teamMemberIds($a);}/** Handles the next number operation for the current WorkIntel workflow. */ private function nextNumber(int $ws):string{return 'WO-'.now()->format('Y').'-'.str_pad((string)(FieldWorkOrder::where('workspace_id',$ws)->count()+1),5,'0',STR_PAD_LEFT);}}
